settings.custom_css:
selector .lakit-bannerlist__item{
    position: sticky;
    top: calc(var(--lakit-header-height,0) + var(--lakit-adminbar-height, 0));
}
selector .lakit-bannerlist__inner {
    width: 42%;
    margin-bottom: var(--lakit-bannerlist-row-gap, 0)
}
selector .lakit-bannerlist__item:nth-child(2n) .lakit-bannerlist__inner{
    margin-left: auto;
}
@media(max-width: 640px){
    selector .lakit-bannerlist__inner {
        width: 47%;
    }
}
